/**
 * @summary Create bill for order
 */
export const createBillBodyDiscountMin = 0;

export const CreateBillBody = zod.object({
  orderId: zod.number(),
  discount: zod.number().min(createBillBodyDiscountMin).optional(),
  dueDate: zod.string().nullish(),
  // Idempotency key (UUID v4) — generated by the client before the first
  // attempt. If the server has already processed a bill for this key, it
  // returns the existing bill without creating a duplicate.
  clientRef: zod.string().uuid().optional(),
});

